mapper.select:
select u.user_id,u.dept_id,u.user_name,u.nick_name,u.email,u.phoneNumber,u.sex,u.avatar,u.`password`,
u.`status`,u.user_type,u.del_flag,u.idcard,u.personalProfile,u.place,u.is_blacklist,u.parent_id
from lm_user u
left join lm_user_role ur on u.user_id = ur.user_id
left join lm_role r on r.role_id = ur.role_id
where u.del_flag = '0'

      and u.user_id = #{userId}


     and u.user_type = #{userType}


     and r.role_id = #{roleId}

    limit 1

mapper.update:
update lm_user
user_name = #{userName}, nick_name = #{nickName}, email = #{email}, phoneNumber = #{phoneNumber}, sex = #{sex}, avatar = #{avatar}, `password` = #{password}, update_by = #{updateBy}, place = #{place}, personalProfile=#{personalProfile}, idcard=#{idcard}, update_time = sysdate()
where user_id = #{userId}

mapper.select:
select u.user_id userId,u.user_name userName,u.nick_name nikName,u.idcard,u.phoneNumber
from lm_user u
         left join lm_user_role ur on u.user_id = ur.user_id
         left join lm_role r on r.role_id = ur.role_id
where u.del_flag = '0'
    and u.is_blacklist = 0

      and u.user_type = #{userType}


      and u.parent_id = #{parentId}


      and r.role_id = #{roleId}
